'use strict';

const QUESTIONS = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed programming languages?',
    helpText: 'Static typing means variable types are checked at compile time, before the program runs.',
    choices: [
      { id: 'q1-a', text: 'JavaScript', correct: false },
      { id: 'q1-b', text: 'TypeScript', correct: true },
      { id: 'q1-c', text: 'Java', correct: true },
      { id: 'q1-d', text: 'Python', correct: false },
    ],
  },
  {
    id: 'q2',
    text: 'Which languages compile directly to native machine code?',
    choices: [
      { id: 'q2-a', text: 'Ruby', correct: false },
      { id: 'q2-b', text: 'C++', correct: true },
      { id: 'q2-c', text: 'Rust', correct: true },
      { id: 'q2-d', text: 'PHP', correct: false },
    ],
  },
  {
    id: 'q3',
    text: 'Which of the following languages primarily support the functional programming paradigm?',
    choices: [
      { id: 'q3-a', text: 'Haskell', correct: true },
      { id: 'q3-b', text: 'C', correct: false },
      { id: 'q3-c', text: 'Erlang', correct: true },
      { id: 'q3-d', text: 'Java', correct: false },
    ],
  },
];

const form = document.getElementById('quiz-form');
const submitBtn = document.getElementById('submit-btn');
const retryBtn = document.getElementById('retry-btn');
const resultSummary = document.getElementById('result-summary');
const scoreDisplay = document.getElementById('score-display');
const scoreSub = document.getElementById('score-sub');
const liveRegion = document.getElementById('live-region');

function getChecked(questionId) {
  return [...form.querySelectorAll(`input[name="${questionId}"]:checked`)].map(
    (el) => el.value,
  );
}

function evaluateQuestion(question) {
  const correctIds = question.choices
    .filter((c) => c.correct)
    .map((c) => c.id);
  const selected = getChecked(question.id);

  const allCorrectSelected = correctIds.every((id) => selected.includes(id));
  const noIncorrectSelected = selected.every((id) => correctIds.includes(id));
  return allCorrectSelected && noIncorrectSelected;
}

function applyResults() {
  let score = 0;

  QUESTIONS.forEach((question) => {
    const isCorrect = evaluateQuestion(question);
    if (isCorrect) score++;

    const fieldDiv = document.getElementById(`field-${question.id}`);
    fieldDiv.classList.toggle('is-correct', isCorrect);
    fieldDiv.classList.toggle('is-incorrect', !isCorrect);

    const correctIds = question.choices
      .filter((c) => c.correct)
      .map((c) => c.id);
    const selected = getChecked(question.id);

    question.choices.forEach((choice) => {
      const label = document.getElementById(`label-${choice.id}`);
      const indicator = label.querySelector('.choice-indicator');
      const input = document.getElementById(choice.id);

      input.disabled = true;
      label.classList.remove('result-correct', 'result-incorrect', 'result-missed');
      indicator.textContent = '';

      const wasSelected = selected.includes(choice.id);

      if (wasSelected && choice.correct) {
        label.classList.add('result-correct');
        indicator.textContent = '✓ Correct';
      } else if (wasSelected && !choice.correct) {
        label.classList.add('result-incorrect');
        indicator.textContent = '✗ Wrong';
      } else if (!wasSelected && choice.correct) {
        label.classList.add('result-missed');
        indicator.textContent = '↑ Missed';
      }
    });
  });

  return score;
}

function showResults(score) {
  const total = QUESTIONS.length;
  const pct = Math.round((score / total) * 100);

  scoreDisplay.textContent = `${score}/${total}`;
  scoreSub.textContent =
    score === total
      ? 'Perfect score! Excellent work.'
      : score >= Math.ceil(total / 2)
      ? `${pct}% — Nice effort! Review the highlighted answers.`
      : `${pct}% — Keep practising! Review the highlighted answers below.`;

  resultSummary.classList.add('visible');
  submitBtn.disabled = true;
  submitBtn.setAttribute('aria-disabled', 'true');

  // Announce result to screen readers
  liveRegion.textContent = `Quiz submitted. You scored ${score} out of ${total}.`;

  // Move focus to summary
  resultSummary.focus();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const score = applyResults();
  showResults(score);
});

retryBtn.addEventListener('click', () => {
  // Reset all inputs
  form.querySelectorAll('input[type="checkbox"]').forEach((input) => {
    input.checked = false;
    input.disabled = false;
  });

  // Remove result classes
  QUESTIONS.forEach((question) => {
    const fieldDiv = document.getElementById(`field-${question.id}`);
    fieldDiv.classList.remove('is-correct', 'is-incorrect');

    question.choices.forEach((choice) => {
      const label = document.getElementById(`label-${choice.id}`);
      const indicator = label.querySelector('.choice-indicator');
      label.classList.remove('result-correct', 'result-incorrect', 'result-missed');
      indicator.textContent = '';
    });
  });

  resultSummary.classList.remove('visible');
  submitBtn.disabled = false;
  submitBtn.removeAttribute('aria-disabled');

  liveRegion.textContent = 'Quiz reset. Good luck!';

  // Return focus to first checkbox
  form.querySelector('input[type="checkbox"]').focus();
});

