}

.subtitle {
  color: var(--color-text-muted);
  font-size: 0.95rem;
}

/* Quiz form */
#quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--color-border-focus);
}

.form-field.is-correct {
  border-color: var(--color-correct);
  background: linear-gradient(135deg, var(--color-surface), var(--color-correct-dim));
}

.form-field.is-incorrect {
  border-color: var(--color-incorrect);
  background: linear-gradient(135deg, var(--color-surface), var(--color-incorrect-dim));
}

fieldset {
  border: none;
  padding: 0;
  min-width: 0;
}

.question-header {
  display: flex;
  align-items: baseline;
  gap: 0.65rem;
  margin-bottom: 1rem;
}

.question-number {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.6rem;
  height: 1.6rem;
  background: var(--color-accent-dim);
  border: 1px solid rgba(123, 108, 246, 0.3);
  border-radius: 50%;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--color-accent-hover);
