.question-header::after {
  content: "";
  display: table;
  clear: both;
}

.help-text {
  font-size: 0.82rem;
  color: var(--color-text-muted);
  margin-bottom: 1rem;
  padding: 0.5rem 0.75rem;
  background: var(--color-surface-raised);
  border-left: 3px solid var(--color-accent);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  line-height: 1.5;
}

.choices {
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.choice-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.7rem 0.9rem;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background var(--transition), border-color var(--transition);
  user-select: none;
}

.choice-label:hover {
  background: rgba(123, 108, 246, 0.08);
  border-color: rgba(123, 108, 246, 0.35);
}

.choice-label:has(input:checked) {
  background: var(--color-accent-dim);
  border-color: rgba(123, 108, 246, 0.5);
}

/* Custom checkbox */
.choice-label input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid var(--color-neutral-check);
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
  position: relative;
}

.choice-label input[type="checkbox"]:checked {
  background: var(--color-accent);
  border-color: var(--color-accent);
}

.choice-label input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  left: 3px;
  top: 0px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.choice-label input[type="checkbox"]:focus-visible {
  outline: 2.5px solid var(--color-border-focus);
  outline-offset: 2px;
}

.choice-label input[type="checkbox"]:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.choice-label:has(input:disabled) {
  cursor: not-allowed;
}

.choice-text {
  font-size: 0.93rem;
  color: var(--color-text);
  line-height: 1.4;
}

/* Result indicators on choices */
.choice-label.result-correct {
  border-color: var(--color-correct);
  background: var(--color-correct-dim);
}

.choice-label.result-incorrect {
  border-color: var(--color-incorrect);
  background: var(--color-incorrect-dim);
}

.choice-label.result-missed {
  border-color: var(--color-correct);
  border-style: dashed;
  background: transparent;
}

.choice-indicator {
  margin-left: auto;
  font-size: 0.85rem;
  font-weight: 600;
  flex-shrink: 0;
}

.choice-label.result-correct .choice-indicator { color: var(--color-correct); }
.choice-label.result-incorrect .choice-indicator { color: var(--color-incorrect); }
.choice-label.result-missed .choice-indicator { color: var(--color-correct); }

/* Submit area */
.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 0.5rem;
}

#submit-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.75rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 0.95rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
