}

#submit-btn:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 20px rgba(123, 108, 246, 0.5);
  transform: translateY(-1px);
}

#submit-btn:active {
  transform: translateY(0);
}

#submit-btn:focus-visible {
  outline: 2.5px solid var(--color-border-focus);
  outline-offset: 3px;
}

#submit-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Score card */
#result-summary {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  text-align: center;
  display: none;
}

#result-summary.visible {
  display: block;
}

.score-ring {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 5rem;
  height: 5rem;
  border-radius: 50%;
  background: var(--color-accent-dim);
  border: 3px solid var(--color-accent);
  font-size: 1.6rem;
  font-weight: 800;
  color: var(--color-accent-hover);
  margin-bottom: 1rem;
}

.score-label {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.35rem;
}

.score-sub {
  font-size: 0.88rem;
  color: var(--color-text-muted);
  margin-bottom: 1.25rem;
}

#retry-btn {
  padding: 0.6rem 1.4rem;
  background: transparent;
  color: var(--color-accent-hover);
  border: 1.5px solid var(--color-accent);
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}

#retry-btn:hover {
  background: var(--color-accent-dim);
}

#retry-btn:focus-visible {
  outline: 2.5px solid var(--color-border-focus);
  outline-offset: 3px;
}

/* Live region */
#live-region {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Responsive reflow at 320px */
@media (max-width: 400px) {
  .form-field {
    padding: 1.1rem;
  }
  .question-header {
    flex-wrap: wrap;
  }
}

@media (forced-colors: active) {
