  #submit-btn {
    background: ButtonText;
    color: ButtonFace;
    border: 1px solid ButtonBorder;
  }
  .choice-label {
    border-color: ButtonBorder;
  }
  .choice-label:has(input:checked) {
    border-color: Highlight;
  }
}
